<?php require 'config.php'; $page_title='Create account — HOSTNEIL'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$d=store_read();$exists=false;foreach($d['users'] as $u)if($u['email']===$email)$exists=true;if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)$err='Use a name, valid email, and password of at least 10 characters.';elseif($exists)$err='An account with this email already exists.';else{$d['users'][]=['name'=>$name,'email'=>$email,'password_hash'=>password_hash($pass,PASSWORD_DEFAULT),'created'=>date('Y-m-d')];store_write($d);session_regenerate_id(true);$_SESSION['user_email']=$email;flash('Account created successfully.');redirect('dashboard.php');}} require 'includes/header.php'; ?><section class="section"><form class="formbox" method="post"><span class="eyebrow">CUSTOMER ACCOUNT</span><h2>Create account</h2><?php if($err): ?><div class="flash error"><?= h($err) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (minimum 10 characters)<input type="password" name="password" minlength="10" required></label><button class="btn full">Register</button><p class="small">Already registered? <a class="accent" href="login.php">Log in</a></p></form></section><?php require 'includes/footer.php'; ?>